-- Run this whole file once in Supabase: SQL Editor → New query → Run.
create type public.app_role as enum ('customer','admin','superadmin');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade,email text unique,role public.app_role not null default 'customer',created_at timestamptz not null default now());
create table public.shipments (shipment_key text primary key check (shipment_key ~ '^[A-Za-z0-9_-]{4,64}$'),data jsonb not null default '{}'::jsonb,map_x numeric not null default 50 check(map_x between 0 and 100),map_y numeric not null default 50 check(map_y between 0 and 100),updated_at timestamptz not null default now(),updated_by uuid references auth.users(id));
create table public.activity (id bigint generated always as identity primary key,type text not null,shipment_key text,actor_id uuid references auth.users(id),actor_email text,created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.shipments enable row level security; alter table public.activity enable row level security;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,email) values(new.id,new.email); return new; end;$$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.my_role() returns text language sql security definer set search_path=public stable as $$select role::text from public.profiles where id=auth.uid()$$;
create or replace function public.is_staff() returns boolean language sql security definer set search_path=public stable as $$select coalesce((select role in ('admin','superadmin') from public.profiles where id=auth.uid()),false)$$;
create or replace function public.is_superadmin() returns boolean language sql security definer set search_path=public stable as $$select coalesce((select role='superadmin' from public.profiles where id=auth.uid()),false)$$;
create or replace function public.get_public_tracking(p_key text) returns jsonb language plpgsql security definer set search_path=public as $$declare s public.shipments%rowtype;begin select * into s from public.shipments where shipment_key=p_key; if not found then return null;end if;return s.data || jsonb_build_object('key',s.shipment_key,'Map X',s.map_x,'Map Y',s.map_y);end;$$;
create or replace function public.list_shipments() returns setof jsonb language sql security definer set search_path=public as $$select jsonb_set(jsonb_set(s.data,'{Map X}',to_jsonb(s.map_x)),'{Map Y}',to_jsonb(s.map_y)) from public.shipments s where public.is_staff() order by s.updated_at desc$$;
create or replace function public.save_shipment(p_data jsonb) returns text language plpgsql security definer set search_path=public as $$declare k text:=trim(p_data->>'Shipment Key'); x numeric:=coalesce((p_data->>'Map X')::numeric,50);y numeric:=coalesce((p_data->>'Map Y')::numeric,50);begin if not public.is_staff() then raise exception 'not authorised';end if;if k !~ '^[A-Za-z0-9_-]{4,64}$' then raise exception 'invalid shipment key';end if;insert into public.shipments(shipment_key,data,map_x,map_y,updated_by) values(k,p_data - 'Map X' - 'Map Y',x,y,auth.uid()) on conflict(shipment_key) do update set data=excluded.data,map_x=excluded.map_x,map_y=excluded.map_y,updated_at=now(),updated_by=auth.uid();insert into public.activity(type,shipment_key,actor_id,actor_email) select 'shipment.saved',k,auth.uid(),email from public.profiles where id=auth.uid();return k;end;$$;
create or replace function public.superadmin_data() returns jsonb language plpgsql security definer set search_path=public as $$begin if not public.is_superadmin() then raise exception 'not authorised';end if;return jsonb_build_object('admins',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'email',email,'role',role,'created_at',created_at) order by created_at desc),'[]'::jsonb) from profiles where role in ('admin','superadmin')),'activity',(select coalesce(jsonb_agg(jsonb_build_object('type',type,'shipment_key',shipment_key,'actor_email',actor_email,'created_at',created_at) order by created_at desc),'[]'::jsonb) from (select * from activity order by created_at desc limit 200) a),'users',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'email',email,'role',role) order by created_at desc),'[]'::jsonb) from profiles));end;$$;
create or replace function public.set_user_role(p_id uuid,p_role public.app_role) returns void language plpgsql security definer set search_path=public as $$begin if not public.is_superadmin() then raise exception 'not authorised';end if;if p_role='superadmin' then raise exception 'superadmin role cannot be assigned from the website';end if;update profiles set role=p_role where id=p_id;insert into activity(type,actor_id,actor_email) select 'user.role_changed:'||p_role,auth.uid(),email from profiles where id=auth.uid();end;$$;
revoke all on public.profiles,public.shipments,public.activity from anon,authenticated;
grant execute on function public.get_public_tracking(text) to anon,authenticated;grant execute on function public.my_role() to authenticated;grant execute on function public.list_shipments(),public.save_shipment(jsonb),public.superadmin_data(),public.set_user_role(uuid,public.app_role) to authenticated;
